CREATE TABLE IF NOT EXISTS cdc_outbox (
  id                BIGSERIAL PRIMARY KEY,
  table_name        TEXT        NOT NULL,
  operation         TEXT        NOT NULL CHECK (operation IN ('INSERT', 'UPDATE', 'DELETE')),
  row_id            TEXT,
  payload           JSONB       NOT NULL,
  old_payload       JSONB,
  status            TEXT        NOT NULL DEFAULT 'pending',
  attempts          INT         NOT NULL DEFAULT 0,
  delivered_targets JSONB       NOT NULL DEFAULT '[]'::jsonb,
  last_error        TEXT,
  locked_until      TIMESTAMPTZ,
  next_attempt_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  delivered_at      TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_cdc_outbox_pick ON cdc_outbox (status, next_attempt_at, id);
CREATE INDEX IF NOT EXISTS idx_cdc_outbox_row ON cdc_outbox (table_name, row_id, id);

CREATE OR REPLACE FUNCTION cdc_capture() RETURNS trigger AS $fn$
BEGIN
  IF TG_OP = 'DELETE' THEN
    INSERT INTO cdc_outbox (table_name, operation, row_id, payload)
    VALUES (TG_TABLE_NAME, 'DELETE', to_jsonb(OLD) ->> 'id', to_jsonb(OLD));
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' THEN
    IF to_jsonb(NEW) IS NOT DISTINCT FROM to_jsonb(OLD) THEN RETURN NEW; END IF;
    INSERT INTO cdc_outbox (table_name, operation, row_id, payload, old_payload)
    VALUES (TG_TABLE_NAME, 'UPDATE', to_jsonb(NEW) ->> 'id', to_jsonb(NEW), to_jsonb(OLD));
    RETURN NEW;
  ELSE
    INSERT INTO cdc_outbox (table_name, operation, row_id, payload)
    VALUES (TG_TABLE_NAME, 'INSERT', to_jsonb(NEW) ->> 'id', to_jsonb(NEW));
    RETURN NEW;
  END IF;
END;
$fn$ LANGUAGE plpgsql;

-- Edit the table name below (it needs an "id" column and an "email" column), or add one trigger per table.
DO $do$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_cdc_customers') THEN
    CREATE TRIGGER trg_cdc_customers AFTER INSERT OR UPDATE OR DELETE ON public.customers
    FOR EACH ROW EXECUTE FUNCTION cdc_capture();
  END IF;
END
$do$;
SELECT 'cdc_ready' AS status;

