const cfg = $('Set Sync Config').first().json;
const enabled = String(cfg.enabledTargets).split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const parse = v => { if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { return null; } } return v; };
// Oldest change first, so every row is delivered in the order it changed
const events = $input.all().map(i => i.json).sort((a, b) => Number(a.id) - Number(b.id));
const tasks = [];

for (const ev of events) {
  const payload = parse(ev.payload) || {};
  // Targets that already succeeded (or were rejected for good, marked with "!") are never re-sent on retry
  const done = new Set((parse(ev.delivered_targets) || []).map(t => String(t).replace(/^!/, '')));
  const email = String(payload.email || '').trim().toLowerCase();
  const op = ev.operation;
  const planned = [];

  if (enabled.includes('hubspot') && !done.has('hubspot') && email && op !== 'DELETE') {
    planned.push({ target: 'hubspot', request: { method: 'POST', url: 'https://api.hubapi.com/crm/v3/objects/contacts/batch/upsert',
      body: { inputs: [{ idProperty: 'email', id: email, properties: { email, firstname: payload.first_name || '', lastname: payload.last_name || '', phone: payload.phone || '', company: payload.company || '' } }] } } });
  }
  if (enabled.includes('mailchimp') && !done.has('mailchimp') && email) {
    const url = 'https://' + cfg.mailchimpDc + '.api.mailchimp.com/3.0/lists/' + cfg.mailchimpListId + '/members/' + ev.email_md5;
    planned.push({ target: 'mailchimp', request: op === 'DELETE'
      ? { method: 'PATCH', url, body: { status: 'unsubscribed' } }
      : { method: 'PUT', url, body: { email_address: email, status_if_new: 'subscribed', merge_fields: { FNAME: payload.first_name || '', LNAME: payload.last_name || '' } } } });
  }
  if (enabled.includes('slack') && !done.has('slack')) {
    planned.push({ target: 'slack', request: { method: 'POST', url: cfg.slackWebhookUrl,
      body: { text: 'CDC ' + op + ' on ' + ev.table_name + ' #' + ev.row_id + (email ? ' (' + email + ')' : '') } } });
  }
  // Every event needs at least one task so it is always finalized
  if (!planned.length) planned.push({ target: 'none', request: null });
  for (const p of planned) tasks.push({ json: { eventId: ev.id, attempts: Number(ev.attempts), op, ...p } });
}
return tasks;

const t = $('Loop Over Deliveries').first().json;
const r = $input.first().json || {};
let ok = false, permanent = false, error = null, sc = null;

if (t.target === 'none') {
  ok = true;
} else {
  sc = Number(r.statusCode) || 0;
  // A 404 when unsubscribing means the member is already gone, which is the desired end state
  ok = (sc >= 200 && sc < 300) || (t.op === 'DELETE' && t.target === 'mailchimp' && sc === 404);
  if (!ok) {
    error = t.target + ': ' + (sc ? 'HTTP ' + sc : String((r.error && r.error.message) || 'request failed')).slice(0, 200);
    // 4xx (except timeout / rate limit) will never succeed on retry
    permanent = sc >= 400 && sc < 500 && sc !== 408 && sc !== 429;
  }
}
return [{ json: { eventId: t.eventId, target: t.target, ok, permanent, error, statusCode: sc } }];

const cfg = $('Set Sync Config').first().json;
const events = $('Postgres - Claim Outbox Batch').all().map(i => i.json);
const results = $input.all().map(i => i.json);
const parse = v => { if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { return null; } } return v; };
const maxAttempts = Number(cfg.maxAttempts) || 5;
const base = Number(cfg.backoffBaseSeconds) || 30, max = Number(cfg.backoffMaxSeconds) || 3600;
const out = [];

for (const ev of events) {
  const attempts = Number(ev.attempts);
  const delivered = new Set(parse(ev.delivered_targets) || []);
  let retryable = false, failed = false;
  const errors = [];

  for (const r of results.filter(x => String(x.eventId) === String(ev.id))) {
    if (r.target === 'none') continue;
    if (r.ok) { delivered.add(r.target); continue; }
    failed = true; errors.push(r.error);
    if (r.permanent) delivered.add('!' + r.target); else retryable = true;
  }

  let status = 'delivered', delay = 0;
  if (failed) {
    if (retryable && attempts < maxAttempts) {
      status = 'retry';
      delay = Math.round(Math.min(max, base * Math.pow(2, attempts - 1)) * (1 + Math.random() * 0.2));
    } else status = 'dead';   // permanent rejection or attempts exhausted: needs a human
  }
  out.push({ json: { id: ev.id, status, attempts, delaySeconds: delay, deliveredTargets: JSON.stringify([...delivered]), lastError: errors.join(' | ') } });
}
return out;

const rows = $('Code - Finalize Events').all().map(i => i.json);
const count = s => rows.filter(r => r.status === s).length;
const dead = rows.filter(r => r.status === 'dead');
const summary = { total: rows.length, delivered: count('delivered'), retry: count('retry'), dead: dead.length, deadIds: dead.map(r => r.id) };
const text = ':rotating_light: CDC sync: ' + summary.dead + ' event(s) dead-lettered (ids: ' + summary.deadIds.join(', ') + '). Review last_error in cdc_outbox, then POST /cdc-requeue.';
return [{ json: { ...summary, hasDead: summary.dead > 0, text } }];

const b = $input.first().json.body || {};
const ids = Array.isArray(b.ids) ? b.ids.map(String) : [];
const clean = ids.filter(x => /^\d{1,18}$/.test(x));
const valid = clean.length > 0 && clean.length <= 500 && clean.length === ids.length;
return [{ json: { valid, idsCsv: clean.join(','), validationError: valid ? null : 'body.ids must be an array of 1-500 numeric event ids' } }];
